"""Browser page for the supervised, simulated payment demo."""

HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>掌纹支付演示</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#17212b;font:16px system-ui,sans-serif}header,main{max-width:1050px;margin:auto;padding:18px}header{display:flex;align-items:center;justify-content:space-between}h1{margin:0;font-size:1.6rem}h2{font-size:1.15rem}main{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(290px,1fr);gap:16px;padding-top:0}.card{background:white;border:1px solid #dce2e8;border-radius:12px;padding:18px}.preview{background:#111;aspect-ratio:4/3;border-radius:8px;overflow:hidden}.preview img{width:100%;height:100%;object-fit:contain}label{display:block;font-weight:600;margin:12px 0 5px}input,button{font:inherit}input{width:100%;padding:10px;border:1px solid #b9c4cc;border-radius:7px}button{border:0;border-radius:8px;padding:11px 15px;background:#125e9c;color:#fff;cursor:pointer;margin-top:12px}button:disabled{opacity:.5;cursor:wait}.secondary{background:#566b7a}.hint{font-size:.9rem;color:#526270;line-height:1.5}.notice{background:#eaf1f7;padding:12px;border-radius:8px;min-height:50px;white-space:pre-wrap;margin-top:12px}.candidate{background:#fff2d7;padding:14px;border-radius:8px;margin-top:12px}#roi{width:128px;height:128px;image-rendering:pixelated;background:#ddd}#roi[hidden],#candidate[hidden]{display:none}@media(max-width:760px){main{grid-template-columns:1fr}}</style></head><body>
<header><h1>掌纹支付 · 基础演示</h1><a href="/collect">采集管理</a></header><main><section class="card"><h2>实时画面</h2><div class="preview"><img id="live" hidden alt="相机画面"></div><p id="camera-status" class="hint" role="status" aria-live="polite">正在连接相机…</p><p id="roi-status" class="hint" role="status" aria-live="polite">等待掌区检测…</p><p class="hint">把手掌放在画面中央。掌区连续就绪后才可开始；每次候选都从当前相机采集一帧并重新定位掌心。无需移开手。</p><img id="roi" hidden alt="自动定位的掌心预览（匹配时会进一步对齐）"></section>
<section class="card"><h2>1. 录入</h2><label for="user">编号</label><input id="user" placeholder="例如 p01_left" pattern="[A-Za-z0-9_-]+"><label for="name">显示姓名</label><input id="name" placeholder="例如 演示用户 A"><label for="hand">本次录入的手</label><select id="hand"><option value="">请选择</option><option value="left">左手</option><option value="right">右手</option></select><p class="hint">全程只放同一只手。当前相机不能可靠自动核实左右手，提交前请再次确认。</p><button id="enroll">开始自动采集</button> <button id="enroll-cancel" class="secondary" hidden>取消 / 重采</button> <button id="enroll-resume" class="secondary" hidden>继续采集</button> <button id="enroll-restore" class="secondary" hidden>重试恢复状态</button> <button id="enroll-commit" hidden>确认同一只手并保存</button><p id="enroll-progress" class="hint" role="status" aria-live="polite"></p><div id="enroll-thumbs" aria-label="本次保留的掌区预览"></div><div id="users" class="hint"></div><hr><h2>2. 模拟支付</h2><p>演示商品 · MOP 20.00</p><button id="identify">拍一张并识别</button><div id="candidate" class="candidate" hidden><strong id="candidate-name"></strong><p id="candidate-score" class="hint"></p><button id="confirm">确认姓名正确，模拟扣款</button> <button id="retry" class="secondary">姓名不对，重拍</button></div><div id="notice" class="notice">先录入，再拍照识别。</div><p class="hint">这是监督式演示；系统只给出候选身份，必须人工确认姓名才会模拟扣款。这里不代表真实支付安全性。</p></section></main>
<script>const $=id=>document.getElementById(id),notice=$('notice'),roi=$('roi'),ENROLLMENT_STORAGE_KEY='palm_demo_enrollment_token';let busy=false,token='',candidateUser='',confirmationUncertain=false,enrollmentToken='',enrollmentStopping=false,enrollmentPaused=false,enrollmentSawNotReady=false,enrollmentSettings=null,enrollmentThumbnails=[];
let waitTimer=null,cameraReady=false,roiReady=false,previewActive=false,previewSequence=0,previewUrl=null,freshTimer=null,statusPollActive=false;
const PREVIEW_MAX_AGE_MS=5000;
function controls(){for(const id of ['enroll','identify'])$(id).disabled=busy||confirmationUncertain||!cameraReady||!roiReady||!!enrollmentToken;for(const id of ['user','name','hand'])$(id).disabled=busy||confirmationUncertain||!!enrollmentToken;$('enroll-cancel').hidden=!enrollmentToken;$('enroll-cancel').disabled=!enrollmentToken;$('enroll-resume').hidden=!enrollmentPaused||!enrollmentToken;$('enroll-resume').disabled=busy||!cameraReady||!roiReady;$('enroll-commit').disabled=!enrollmentToken||busy;for(const id of ['confirm','retry'])$(id).disabled=busy||!token;$('confirm').textContent=confirmationUncertain?'重试获取本次支付结果':'确认姓名正确，模拟扣款';$('retry').textContent=confirmationUncertain?'查询并取消未完成的候选':'姓名不对，重拍'}
function cameraUnavailable(message){cameraReady=false;roiReady=false;clearTimeout(freshTimer);freshTimer=null;$('live').hidden=true;$('live').removeAttribute('src');if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null}$('camera-status').textContent=message;$('roi-status').textContent='掌区状态不可用';controls()}
async function pollStatus(){if(statusPollActive)return;statusPollActive=true;try{const r=await fetch('/api/status?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();const state=d.demo_quality_status??d.quality_status??'状态未知';const count=Number(d.demo_quality_consecutive_frames??d.quality_consecutive_frames??0),required=Number(d.demo_quality_required_frames??d.quality_required_frames??5);roiReady=Boolean(d.camera_ready&&d.roi_status_fresh===true&&state==='READY'&&count>=required);const reason=d.demo_quality_reason??d.quality_reason;const hints={sharpness_below_minimum:'画面偏模糊，请稳住手掌并等待清晰预览',contrast_below_minimum:'对比度偏低，请调整光线或手掌位置',tracker_status_fixed:'当前模式无法确认掌区，请启用动态掌区检测',roi_unstable:'掌区位置不稳定，请保持手掌稳定'};const detail=reason?(' · '+(hints[reason]||reason)):'';const freshness=d.roi_status_fresh===false?' · 检测结果已过期':'';$('roi-status').textContent=roiReady?`掌区画质已就绪 (${count}/${required})`:`掌区未就绪：${state} (${count}/${required})${detail}${freshness}`;if(enrollmentPaused&&!roiReady)enrollmentSawNotReady=true;controls();if(enrollmentPaused&&enrollmentSawNotReady&&roiReady&&!busy)void resumeEnrollment()}catch(e){roiReady=false;if(enrollmentPaused)enrollmentSawNotReady=true;$('roi-status').textContent='掌区状态不可用，录入与识别已暂停';controls()}finally{statusPollActive=false;setTimeout(pollStatus,500)}}
async function preview(){
 if(previewActive)return;
 previewActive=true;const sequence=++previewSequence,controller=new AbortController();let expired=false,next=null,timeout;
 const deadline=new Promise((_,reject)=>{timeout=setTimeout(()=>{expired=true;controller.abort();reject(Error('预览超时'))},PREVIEW_MAX_AGE_MS)});
 try{
  const blob=await Promise.race([(async()=>{const r=await fetch('/frame.jpg?t='+Date.now(),{cache:'no-store',signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return r.blob()})(),deadline]);
  if(expired||sequence!==previewSequence)return;
  next=URL.createObjectURL(blob);
  await Promise.race([new Promise((resolve,reject)=>{const live=$('live');live.onload=resolve;live.onerror=()=>reject(Error('预览图像无法显示'));live.src=next}),deadline]);
  if(expired||sequence!==previewSequence)return;
  if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=next;next=null;cameraReady=true;$('live').hidden=false;$('camera-status').textContent='相机已连接 · 实时预览';clearTimeout(freshTimer);freshTimer=setTimeout(()=>cameraUnavailable('画面已停止更新，请检查相机连接；恢复后可继续拍摄。'),PREVIEW_MAX_AGE_MS);controls();
 }catch(e){if(sequence===previewSequence)cameraUnavailable('相机预览不可用，请检查连接；恢复后可继续拍摄。')}
 finally{clearTimeout(timeout);$('live').onload=null;$('live').onerror=null;if(next)URL.revokeObjectURL(next);previewActive=false;setTimeout(preview,300)}
}
function lock(value){busy=value;if(!value){clearInterval(waitTimer);waitTimer=null}controls()}
function waiting(message){const start=Date.now();notice.textContent=message;clearInterval(waitTimer);waitTimer=setInterval(()=>{notice.textContent=message+' 已等待 '+Math.floor((Date.now()-start)/1000)+' 秒。'},1000)}
async function useContinuousFocusIfAvailable(){try{const r=await fetch('/api/camera/focus');const d=await r.json();if(d.supported&&!d.continuous)await post('/api/camera/focus',{})}catch(e){/* Image quality gate remains active when focus control is unavailable. */}}
async function post(path,payload){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.message||'操作失败');return d}
function clearStoredEnrollment(){try{sessionStorage.removeItem(ENROLLMENT_STORAGE_KEY)}catch(e){}}
async function persistEnrollmentToken(value){try{sessionStorage.setItem(ENROLLMENT_STORAGE_KEY,value)}catch(e){try{await post('/api/demo/enroll/cancel',{token:value});clearStoredEnrollment();enrollmentToken='';enrollmentSettings=null;throw Error('浏览器无法保存刷新恢复信息，本次录入已取消。')}catch(cancelError){if(!enrollmentToken)throw cancelError;throw Error('浏览器无法保存刷新恢复信息，自动取消也未确认；请在当前页面手动取消。')}}}
async function restoreEnrollment(){let saved;try{saved=sessionStorage.getItem(ENROLLMENT_STORAGE_KEY)}catch(e){return}if(!saved)return;try{const state=await post('/api/demo/enroll/status',{token:saved});if(state.status==='EXPIRED'){clearStoredEnrollment();enrollmentToken='';enrollmentSettings=null;enrollmentPaused=false;$('enroll-restore').hidden=true;controls();notice.textContent='之前的录入会话已超时，未保存的候选已清除；可以重新开始。';return}enrollmentToken=saved;enrollmentSettings=state;$('enroll-restore').hidden=true;$('user').value=state.user_id;$('name').value=state.display_name;$('hand').value=state.hand;enrollmentThumbnails=state.selected_roi_images||[];$('enroll-thumbs').innerHTML=enrollmentThumbnails.map((image,index)=>`<img alt="自动选中的掌区 ${index+1}" width="64" height="64" src="data:image/png;base64,${image}"> `).join('');$('enroll-progress').textContent=`已恢复录入：候选 ${state.candidate_pool_count}/${state.candidate_pool_required} 张；已选 ${state.kept}/${state.required} 张；已拍 ${state.attempts} 张（质量重试 ${state.quality_failures}/${state.max_quality_failures}）。`;if(state.status==='READY'){$('enroll-commit').hidden=false;enrollmentPaused=false;notice.textContent='已恢复已选出的五张掌区，请核对预览并确认同一只手后保存。'}else if(state.status==='STOPPED'){enrollmentPaused=false;$('enroll-commit').hidden=true;notice.textContent='已恢复录入会话，但已达到重试上限；请取消后重新开始。'}else{enrollmentPaused=true;enrollmentSawNotReady=true;$('enroll-commit').hidden=true;notice.textContent='已恢复未完成的录入；预览就绪后将继续自动采集，也可手动继续或取消。'}controls()}catch(e){enrollmentToken=saved;enrollmentSettings=null;enrollmentPaused=false;enrollmentSawNotReady=false;$('enroll-restore').hidden=false;$('enroll-commit').hidden=true;controls();notice.textContent='暂时无法确认之前的录入状态。恢复 token 已保留；请重试查询，或取消这次未完成的录入。'}}
async function users(){try{const r=await fetch('/api/demo/users');const d=await r.json();$('users').textContent=d.users.length?'已录入：'+d.users.map(x=>x.display_name+' ('+x.user_id+')'+(x.needs_reenrollment?' [需用原编号重新录入]':'')).join('、'):'尚未录入'}catch(e){$('users').textContent='暂时无法读取录入列表'}}users();
async function runEnrollmentSteps(settings){let last;while(!enrollmentStopping){last=await post('/api/demo/enroll/step',{token:enrollmentToken});$('enroll-progress').textContent=`候选 ${last.candidate_pool_count??last.kept}/${last.candidate_pool_required??settings.candidate_pool_required??8} 张；已选 ${last.kept}/${last.required} 张；已拍 ${last.attempts} 张（重复跳过 ${last.duplicate_frames||0} 张，质量重试 ${last.quality_failures||0}/${settings.max_quality_failures}）。`;notice.textContent=last.reason||'正在自动筛选清晰、姿态与纹理不同的掌区…';if(last.selected_roi_images){enrollmentThumbnails=last.selected_roi_images;$('enroll-thumbs').innerHTML=enrollmentThumbnails.map((image,index)=>`<img alt="自动选中的掌区 ${index+1}" width="64" height="64" src="data:image/png;base64,${image}"> `).join('')}if(last.capture_failure==='CAMERA_UNAVAILABLE'){enrollmentPaused=true;enrollmentSawNotReady=!cameraReady||!roiReady;controls();break}if(last.status==='READY'||last.status==='STOPPED'||last.status==='NO_HAND')break;if(last.retry_after_ms)await new Promise(resolve=>setTimeout(resolve,last.retry_after_ms))}if(enrollmentStopping)return;if(last.status==='READY'){$('enroll-commit').hidden=false;enrollmentPaused=false;enrollmentSawNotReady=false;notice.textContent='已从候选画面中选出五张。请核对下方预览并确认全程是同一只手，再保存。'}else if(last.status==='NO_HAND'){enrollmentPaused=true;enrollmentSawNotReady=false;roiReady=false;controls();notice.textContent=last.reason}else if(last.capture_failure==='CAMERA_UNAVAILABLE'){notice.textContent=(last.reason||'相机暂时不可用。')+' 录入已暂停；相机状态恢复后会自动继续，也可在画面就绪时手动继续。'}else notice.textContent=last.reason}
$('enroll').onclick=async()=>{if(busy||confirmationUncertain||!cameraReady||!roiReady)return;const user=$('user').value.trim(),name=$('name').value.trim(),hand=$('hand').value;if(!/^[A-Za-z0-9_-]{1,40}$/.test(user)||!name||!hand){notice.textContent='请填写编号、姓名并选择手别。';return}lock(true);enrollmentStopping=false;enrollmentPaused=false;enrollmentThumbnails=[];$('enroll-thumbs').innerHTML='';try{await useContinuousFocusIfAvailable();enrollmentSettings=await post('/api/demo/enroll/start',{user_id:user,display_name:name,hand});enrollmentToken=enrollmentSettings.token;await persistEnrollmentToken(enrollmentToken);controls();await runEnrollmentSteps(enrollmentSettings)}catch(e){if(enrollmentToken)enrollmentPaused=true;notice.textContent='录入采集失败：'+e.message+(enrollmentToken?'；画面就绪后可继续采集或取消。':'')}finally{lock(false)}};
async function resumeEnrollment(manual=false){if(busy||!enrollmentToken||!enrollmentPaused||!cameraReady||!roiReady||(!manual&&!enrollmentSawNotReady))return;lock(true);enrollmentPaused=false;enrollmentSawNotReady=false;try{await runEnrollmentSteps(enrollmentSettings)}catch(e){enrollmentPaused=true;notice.textContent='继续采集失败：'+e.message+'；画面就绪后可重试或取消。'}finally{lock(false)}}
$('enroll-resume').onclick=()=>resumeEnrollment(true);
$('enroll-restore').onclick=async()=>{if(busy)return;lock(true);try{await restoreEnrollment()}finally{lock(false)}};
$('enroll-cancel').onclick=async()=>{if(!enrollmentToken)return;enrollmentStopping=true;const current=enrollmentToken;$('enroll-cancel').disabled=true;notice.textContent='正在取消，等待当前这张照片拍摄完成…';try{await post('/api/demo/enroll/cancel',{token:current});clearStoredEnrollment();enrollmentToken='';enrollmentPaused=false;enrollmentSettings=null;$('enroll-restore').hidden=true;$('enroll-commit').hidden=true;$('enroll-progress').textContent='已取消，已保留的临时候选没有入库。';enrollmentThumbnails=[];$('enroll-thumbs').innerHTML='';notice.textContent='可调整手掌位置后重新开始。'}catch(e){notice.textContent='取消失败，请重试：'+e.message}finally{controls()}};
$('enroll-commit').onclick=async()=>{if(busy||!enrollmentToken)return;lock(true);try{const d=await post('/api/demo/enroll/commit',{token:enrollmentToken,confirm_hand:$('hand').value});clearStoredEnrollment();enrollmentToken='';enrollmentPaused=false;enrollmentSettings=null;$('enroll-commit').hidden=true;$('enroll-progress').textContent='已保存五张掌纹模板。';notice.textContent=`已录入 ${d.display_name}。模拟余额 MOP ${(d.balance_cents/100).toFixed(2)}。`;await users()}catch(e){notice.textContent='保存失败：'+e.message}finally{lock(false)}};
$('identify').onclick=async()=>{if(busy||confirmationUncertain||!cameraReady||!roiReady)return;lock(true);token='';roi.hidden=true;$('candidate').hidden=true;waiting('正在采集并识别当前画面…');try{const d=await post('/api/demo/identify',{});clearInterval(waitTimer);if(d.roi_image){roi.src='data:image/png;base64,'+d.roi_image;roi.hidden=false}if(d.status==='MATCH'){token=d.token;candidateUser=d.user_id;$('candidate-name').textContent='候选身份：'+d.display_name;$('candidate-score').textContent='距离 '+d.score.toFixed(4)+(d.second_score==null?'':' · 第二名 '+d.second_score.toFixed(4));$('candidate').hidden=false;notice.textContent='请核对姓名；如果不对，点“姓名不对，重拍”。'}else notice.textContent=d.reason==='INCOMPATIBLE_TEMPLATES'?'录入资料需要更新，请用原编号重新录入；已有余额保留。':d.status==='UNKNOWN'?'未识别到已录入手掌；没有扣款。请调整位置后重拍。':'本次结果不明确；没有扣款。请重拍。'}catch(e){notice.textContent='识别失败：'+e.message}finally{lock(false)}};
function paymentResult(d){const state=d.status==='PAID'?d.payment_status:d.status;if(!['SUCCESS','INSUFFICIENT_BALANCE','ERROR'].includes(state))throw Error('未能核实本次支付结果');$('candidate').hidden=true;token='';confirmationUncertain=false;notice.textContent=state==='SUCCESS'?`模拟支付成功：${d.display_name}，MOP ${((d.amount_cents??2000)/100).toFixed(2)}；余额 MOP ${(d.balance_cents/100).toFixed(2)}。`:state==='INSUFFICIENT_BALANCE'?'模拟余额不足；本次没有扣款。':'模拟支付未完成：'+state}
$('retry').onclick=async()=>{if(busy||!token)return;lock(true);try{const d=await post('/api/demo/cancel',{token});if(d.status==='PAID'){paymentResult(d);await users()}else if(d.status==='CANCELLED'){$('candidate').hidden=true;token='';confirmationUncertain=false;notice.textContent='已取消本次候选；没有扣款。请重拍。'}else throw Error('未能核实本次候选状态')}catch(e){notice.textContent='取消或查询未确认，请重试：'+e.message}finally{lock(false)}};
$('confirm').onclick=async()=>{if(busy||!token)return;lock(true);try{const d=await post('/api/demo/confirm',{token,user_id:candidateUser});paymentResult(d);await users()}catch(e){confirmationUncertain=true;notice.textContent='未收到模拟支付确认，状态待核实。请重试获取本次结果，或查询并取消未完成的候选：'+e.message}finally{lock(false)}};
controls();void restoreEnrollment();preview();pollStatus();
</script></body></html>"""
